Input: {"question": "When was Carl Roth born?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0442-9468acb685ff:d00", "start": 0, "end": 130, "text": "Carl Reinhold Roth Carl Reinhold Roth was a Swedish businessman and ironmaster who lived during the late 17th to mid 18th century."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0442-9468acb685ff:d00", "start": 131, "end": 219, "text": "He is best known as the first ironmaster named Roth at the ironworks in Ludvika, Sweden."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0442-9468acb685ff:d00", "start": 220, "end": 291, "text": "Reinhold was in his time one of Stockholm's more prominent businessmen."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0442-9468acb685ff:d00", "start": 292, "end": 510, "text": "He also owned Sunnansjö ironworks and estate, and Skogsegen (Judge Hörneåfor’s ironworks in Västerbotten), devoted himself to the nascent sawmill industry, and was ship-owner of the Augusta (named for his second wife)."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0442-9468acb685ff:d00", "start": 511, "end": 563, "text": "Reinhold was born November 18, 1797 in Lower Fösked."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0442-9468acb685ff:d00", "start": 564, "end": 619, "text": "His career began in Stockholm, where he was employed by"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0442-9468acb685ff:d01", "start": 0, "end": 111, "text": "Carl Reinhold Roth was a Swedish businessman and ironmaster who lived during the late 17th to mid 18th century."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0442-9468acb685ff:d01", "start": 112, "end": 200, "text": "He is best known as the first ironmaster named Roth at the ironworks in Ludvika, Sweden."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0442-9468acb685ff:d01", "start": 201, "end": 272, "text": "Reinhold was in his time one of Stockholm's more prominent businessmen."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0442-9468acb685ff:d01", "start": 273, "end": 491, "text": "He also owned Sunnansjö ironworks and estate, and Skogsegen (Judge Hörneåfor’s ironworks in Västerbotten), devoted himself to the nascent sawmill industry, and was ship-owner of the Augusta (named for his second wife)."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0442-9468acb685ff:d01", "start": 492, "end": 542, "text": "Reinhold was born January 1, 1800 in Lower Fösked."}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0442-9468acb685ff:d01", "start": 543, "end": 598, "text": "His career began in Stockholm, where he was employed by"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0442-9468acb685ff:d02", "start": 0, "end": 97, "text": "Carl Roth II Carl Roth II was a Swedish ironmaster who lived between the 17th and 18th centuries."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0442-9468acb685ff:d02", "start": 98, "end": 234, "text": "He is best known for owning two ironworks in Karlstad Municipality, Värmland County, Sweden: Duvnäs (Duvenäs), and Nedre Fösked (Föske)."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0442-9468acb685ff:d02", "start": 235, "end": 283, "text": "Carl was born on October 12, 1753, in Stockholm."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0442-9468acb685ff:d02", "start": 284, "end": 379, "text": "On June 26, 1764, at the age of 10, he enrolled at Uppsala University under Stockholm's Nation."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0442-9468acb685ff:d02", "start": 380, "end": 533, "text": "After graduating in 1771, he moved with his parents to their estate at Duvnäs where he focused primarily on agriculture and working at the family's mill."}, "D3S6": {"document_number": 3, "doc_id": "ramdocs-0442-9468acb685ff:d02", "start": 534, "end": 586, "text": "Carl was said to have a Godly and humble disposition"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0442-9468acb685ff:d03", "start": 0, "end": 121, "text": "Carl Roth (basketball) Carl William Roth (September 15, 1909 – May 28, 1966) was an American basketball player and coach."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0442-9468acb685ff:d03", "start": 122, "end": 267, "text": "A native of Sheboygan, Wisconsin, Roth attended the University of Wisconsin–Madison and played for their men's basketball team from 1929 to 1932."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0442-9468acb685ff:d03", "start": 268, "end": 366, "text": "Six years later he played in 14 total games for the Sheboygan Red Skins during the 1938–39 season."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0442-9468acb685ff:d03", "start": 367, "end": 465, "text": "The Red Skins were a professional franchise that competed in the National Basketball League (NBL)."}, "D4S5": {"document_number": 4, "doc_id": "ramdocs-0442-9468acb685ff:d03", "start": 466, "end": 571, "text": "Roth stayed with the team as both its legal counsel and in other capacities after his one season playing."}, "D4S6": {"document_number": 4, "doc_id": "ramdocs-0442-9468acb685ff:d03", "start": 572, "end": 598, "text": "He took over as head coach"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0442-9468acb685ff:d04", "start": 0, "end": 624, "text": "Charles II | Biography , Accomplishments , & Facts | Britannica Search Britannica Click here to search Search Britannica Click here to search SUBSCRIBE Login SUBSCRIBE Home History & Society Science & Tech Biographies Animals & Nature Geography & Travel Arts & Culture ProCon Money Games & Quizzes Videos On This Day One Good Fact Dictionary New Articles History & Society Lifestyles & Social Issues Philosophy & Religion Politics , Law & Government World History Science & Tech Health & Medicine Science Technology Biographies Browse Biographies Animals & Nature Birds , Reptiles & Other Vertebrates Bugs , Mollusks & Other"}}, "original_cards": [{"doc_id": "ramdocs-0442-9468acb685ff:d00", "card_id": "ramdocs-0442-9468acb685ff:d00:c0", "entity": "Carl Reinhold Roth", "scope": "Birth date", "claim": "Reinhold was born November 18, 1797 in Lower Fösked.", "answer": "November 18, 1797", "quote": "Reinhold was born November 18, 1797 in Lower Fösked.", "original_document_number": 1}, {"doc_id": "ramdocs-0442-9468acb685ff:d01", "card_id": "ramdocs-0442-9468acb685ff:d01:c0", "entity": "Carl Reinhold Roth", "scope": "Birth date", "claim": "Reinhold was born January 1, 1800 in Lower Fösked.", "answer": "January 1, 1800", "quote": "Reinhold was born January 1, 1800 in Lower Fösked.", "original_document_number": 2}, {"doc_id": "ramdocs-0442-9468acb685ff:d02", "card_id": "ramdocs-0442-9468acb685ff:d02:c0", "entity": "Carl Roth", "scope": "Birth date", "claim": "Carl was born on October 12, 1753, in Stockholm.", "answer": "October 12, 1753", "quote": "Carl was born on October 12, 1753, in Stockholm.", "original_document_number": 3}, {"doc_id": "ramdocs-0442-9468acb685ff:d03", "card_id": "ramdocs-0442-9468acb685ff:d03:c0", "entity": "Carl Roth", "scope": "birth date", "claim": "Carl William Roth was born on September 15, 1909.", "answer": "September 15, 1909", "quote": "Carl Roth (basketball) Carl William Roth (September 15, 1909 – May 28, 1966) was an American basketball player and coach.", "original_document_number": 4}], "current_answers": ["November 18, 1797", "January 1, 1800", "October 12, 1753", "September 15, 1909"], "candidate_answers": [{"candidate_id": "R0", "answer": "November 18, 1797", "origin": "initial"}, {"candidate_id": "R1", "answer": "January 1, 1800", "origin": "initial"}, {"candidate_id": "R2", "answer": "October 12, 1753", "origin": "initial"}, {"candidate_id": "R3", "answer": "September 15, 1909", "origin": "initial"}], "requested_slot_hint": "birth_date"}
